BEGIN;
DO $$
DECLARE
  syllabus jsonb := '{"course-1":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-1-1\">The first client meeting</a></li><li><a href=\"#cfp-class-1-2\">Read the household balance sheet</a></li><li><a href=\"#cfp-class-1-3\">Build a cash flow and debt plan</a></li><li><a href=\"#cfp-class-1-4\">Rates, inflation and calculator setup</a></li><li><a href=\"#cfp-class-1-5\">Fund an education goal</a></li><li><a href=\"#cfp-class-1-6\">Ethics and fiduciary judgment</a></li><li><a href=\"#cfp-class-1-7\">Regulation and consumer protection</a></li><li><a href=\"#cfp-class-1-8\">Behavioral bias and client values</a></li><li><a href=\"#cfp-class-1-9\">Counseling, conflict and crisis</a></li><li><a href=\"#cfp-class-1-10\">Foundations case workshop</a></li></ol></section>","course-2":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-2-1\">Inventory and prioritize exposures</a></li><li><a href=\"#cfp-class-2-2\">Health coverage and social insurance</a></li><li><a href=\"#cfp-class-2-3\">Disability and workers’ compensation</a></li><li><a href=\"#cfp-class-2-4\">Long-term care and caregiving</a></li><li><a href=\"#cfp-class-2-5\">Annuity economics and trade-offs</a></li><li><a href=\"#cfp-class-2-6\">Life insurance structures</a></li><li><a href=\"#cfp-class-2-7\">Quantify coverage and compare policies</a></li><li><a href=\"#cfp-class-2-8\">Property, liability and business coverage</a></li><li><a href=\"#cfp-class-2-9\">Equity compensation and deferred pay</a></li><li><a href=\"#cfp-class-2-10\">Risk and benefits case workshop</a></li></ol></section>","course-3":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-3-1\">Investment vehicles and ownership</a></li><li><a href=\"#cfp-class-3-2\">Risk and market cycles</a></li><li><a href=\"#cfp-class-3-3\">Calculate and interpret returns</a></li><li><a href=\"#cfp-class-3-4\">Value a bond</a></li><li><a href=\"#cfp-class-3-5\">Value a stock</a></li><li><a href=\"#cfp-class-3-6\">Construct an allocation</a></li><li><a href=\"#cfp-class-3-7\">Portfolio theory and pricing models</a></li><li><a href=\"#cfp-class-3-8\">Investment strategies and taxes</a></li><li><a href=\"#cfp-class-3-9\">Alternatives and access to cash</a></li><li><a href=\"#cfp-class-3-10\">Investment case workshop</a></li></ol></section>","course-4":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-4-1\">Tax-year facts and authority</a></li><li><a href=\"#cfp-class-4-2\">Compute taxable income and tax</a></li><li><a href=\"#cfp-class-4-3\">Tax accounting and timing</a></li><li><a href=\"#cfp-class-4-4\">Compare business entities</a></li><li><a href=\"#cfp-class-4-5\">Calculate basis and depreciation</a></li><li><a href=\"#cfp-class-4-6\">Disposition and like-kind exchanges</a></li><li><a href=\"#cfp-class-4-7\">AMT, basis, at-risk and passive losses</a></li><li><a href=\"#cfp-class-4-8\">Trust and estate income tax</a></li><li><a href=\"#cfp-class-4-9\">Giving, divorce and death</a></li><li><a href=\"#cfp-class-4-10\">Tax case workshop</a></li></ol></section>","course-5":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-5-1\">Estimate retirement needs</a></li><li><a href=\"#cfp-class-5-2\">Social Security and Medicare</a></li><li><a href=\"#cfp-class-5-3\">Caregiving and special-needs planning</a></li><li><a href=\"#cfp-class-5-4\">Retirement plan types</a></li><li><a href=\"#cfp-class-5-5\">ERISA, eligibility and vesting</a></li><li><a href=\"#cfp-class-5-6\">Nonqualified and executive benefits</a></li><li><a href=\"#cfp-class-5-7\">Choose a business retirement plan</a></li><li><a href=\"#cfp-class-5-8\">Rollovers and distribution tax</a></li><li><a href=\"#cfp-class-5-9\">Invest and withdraw in retirement</a></li><li><a href=\"#cfp-class-5-10\">Retirement case workshop</a></li></ol></section>","course-6":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-6-1\">Inventory title and beneficiaries</a></li><li><a href=\"#cfp-class-6-2\">Transfers, wills and probate</a></li><li><a href=\"#cfp-class-6-3\">Planning for incapacity</a></li><li><a href=\"#cfp-class-6-4\">Gifts, estate tax and GST</a></li><li><a href=\"#cfp-class-6-5\">Estate liquidity</a></li><li><a href=\"#cfp-class-6-6\">Trust designs and income tax</a></li><li><a href=\"#cfp-class-6-7\">Marital transfers and postmortem planning</a></li><li><a href=\"#cfp-class-6-8\">Family business succession</a></li><li><a href=\"#cfp-class-6-9\">Divorce, unmarried partners and special needs</a></li><li><a href=\"#cfp-class-6-10\">Estate case workshop</a></li></ol></section>","capstone":"<section><h4>Ten-class syllabus</h4><p>Each class is two hours. Follow classes in order and save your work for the capstone.</p><ol><li><a href=\"#cfp-class-7-1\">Open the Rivera capstone</a></li><li><a href=\"#cfp-class-7-2\">Verify the case facts</a></li><li><a href=\"#cfp-class-7-3\">Rank the goals and test alternatives</a></li><li><a href=\"#cfp-class-7-4\">Prepare the risk recommendation</a></li><li><a href=\"#cfp-class-7-5\">Build the investment recommendation</a></li><li><a href=\"#cfp-class-7-6\">Model tax impact</a></li><li><a href=\"#cfp-class-7-7\">Model retirement outcomes</a></li><li><a href=\"#cfp-class-7-8\">Draft estate and succession actions</a></li><li><a href=\"#cfp-class-7-9\">Integrate, implement and monitor</a></li><li><a href=\"#cfp-class-7-10\">Present and defend the plan</a></li></ol></section>","start":"<section><h4>Start the 70-class program</h4><p>There are ten two-hour classes in each of seven courses, including financial plan development. Total class time is 140 hours. Pick a pace that fits your calendar. At two classes a week, the class sequence takes 35 weeks. Independent study, exam practice and revisions are additional.</p><ol><li><a href=\"#course-1\">Planning principles, professional conduct and client psychology</a></li><li><a href=\"#course-2\">Risk management, insurance and employee benefits</a></li><li><a href=\"#course-3\">Investment planning</a></li><li><a href=\"#course-4\">Tax planning</a></li><li><a href=\"#course-5\">Retirement savings and income</a></li><li><a href=\"#course-6\">Estate planning</a></li><li><a href=\"#capstone\">Financial plan development</a></li></ol></section>"}'::jsonb;
  classes jsonb := '[{"id":"cfp-class-1-1","title":"Course 1 · Class 1 · The first client meeting","html":"<h3>Course 1 · Class 1 · The first client meeting</h3><p><a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-2\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the lesson below and the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the example below. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Discovery, scope and professional judgment</h4><p>A planning engagement begins by identifying the decision and the people affected. Gather quantitative facts such as statements and contracts, and qualitative facts such as priorities, tolerance for uncertainty and family responsibilities. Use those facts to select goals, compare the current path with alternatives, develop and present recommendations, then assign implementation and monitoring responsibilities. When providing financial advice under CFP Board’s standards, a CFP professional must act as a fiduciary. Disclose material conflicts, obtain informed consent and manage them. Check the applicable securities, insurance and privacy rules before assuming your role permits an action.</p><h4>Worked example</h4><p>A business owner requests a policy quote for a buyout. The agreement requires the company to purchase the interest, but the owner wants an individual policy naming a spouse. First read the agreement, confirm valuation and obligations, and verify current funding. Then compare proposed ownership and payment paths with counsel. If the advisor earns a commission, explain it and document the alternatives before the client decides.</p><h4>Practice variation</h4><p>A client asks for an IRA rollover and has not provided the employer plan’s fees or distribution terms. What should you do before giving a recommendation?</p><details><summary>Check your work</summary><p>Obtain the missing terms, clarify liquidity and services needed, compare leaving assets in the plan with eligible alternatives, and disclose and manage compensation conflicts. Record who implements and how the decision will be reviewed.</p></details><h4>Related topic lessons</h4><ul><li><a href=\"#topic-7\">Open Topic 7</a></li></ul><h4>Class assignment</h4><p>Write five discovery questions and a scope statement for an owner asking about a buyout.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-2","title":"Course 1 · Class 2 · Read the household balance sheet","html":"<h3>Course 1 · Class 2 · Read the household balance sheet</h3><p><a href=\"#cfp-class-1-1\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-3\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-8\">Open Topic 8</a></li></ul><h4>Class assignment</h4><p>Build the Rivera balance sheet, then label liquid assets, restricted assets and debt.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-3","title":"Course 1 · Class 3 · Build a cash flow and debt plan","html":"<h3>Course 1 · Class 3 · Build a cash flow and debt plan</h3><p><a href=\"#cfp-class-1-2\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-4\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the lesson below and the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the example below. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Cash flow, debt and economic assumptions</h4><p>Net worth is assets less liabilities at a point in time. Cash surplus is income less spending over a period. Use take-home income consistently, separate essential spending from elective spending, and convert irregular bills to monthly amounts. For two debts, compare interest rates and constraints. A higher rate generally gets priority after preserving cash needed to stay current. Use a real return with today-dollar goals and a nominal return with inflation-adjusted future-dollar goals.</p><h4>Worked example</h4><p>A household earns $8,000 take-home. It spends $4,500 on core bills, $1,100 on discretionary items, $600 on debt service, and $2,400 a year on irregular bills. The irregular bills average $200 a month. Surplus is $1,600. Six months of core bills and required debt payments would be $30,600, before adding any irregular bills deemed essential. A $350,000 home is an asset but cannot automatically be used to pay next month’s bills.</p><h4>Practice variation</h4><p>If take-home income declines by $1,200 and spending is unchanged, what is the new surplus? How would you open a discussion with partners who disagree about using reserves?</p><details><summary>Check your work</summary><p>$400. Ask each person what financial outcome they fear most, then compare a cash floor and repayment alternatives. This reveals whether the disagreement is about liquidity, interest or security.</p></details><h4>Related topic lessons</h4><ul><li><a href=\"#topic-9\">Open Topic 9</a></li><li><a href=\"#topic-10\">Open Topic 10</a></li></ul><h4>Class assignment</h4><p>Model a one-month income drop and compare a cash floor with accelerated debt payments.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-4","title":"Course 1 · Class 4 · Rates, inflation and calculator setup","html":"<h3>Course 1 · Class 4 · Rates, inflation and calculator setup</h3><p><a href=\"#cfp-class-1-3\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-5\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the lesson below and the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the example below. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Time value of money and education funding</h4><p>Draw a timeline before touching the calculator. Convert annual rates and periods to the same units. Use FV = PV × (1+r)^n for a lump sum and reverse it for present value. End-of-period contributions earn for one period less than otherwise identical beginning-of-period contributions. When funding education, project tuition growth, subtract grants and earmarked assets, and compare a 529, taxable savings and borrowing by flexibility, risk and eligibility.</p><h4>Worked example</h4><p>Tuition costs $18,000 today and is assumed to rise 3% annually for six years. The projected first bill is about $21,493. At a hypothetical 4% annual return, its deposit today is about $16,987. Separate this first bill from the remaining years and do the same calculation for each. One projected rate is a scenario, so also model lower returns.</p><h4>Practice variation</h4><p>If the required future payment is $20,000 in two years and the assumed return is 5%, what is the present value? What happens if the expected return falls?</p><details><summary>Check your work</summary><p>$20,000 ÷ 1.05² ≈ $18,141. A lower expected return increases the required deposit today.</p></details><h4>Related topic lessons</h4><ul><li><a href=\"#topic-11\">Open Topic 11</a></li><li><a href=\"#topic-12\">Open Topic 12</a></li></ul><h4>Class assignment</h4><p>Convert a nominal return to a real return and solve the tuition deposit at two rates.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-5","title":"Course 1 · Class 5 · Fund an education goal","html":"<h3>Course 1 · Class 5 · Fund an education goal</h3><p><a href=\"#cfp-class-1-4\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-6\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-13\">Open Topic 13</a></li><li><a href=\"#topic-14\">Open Topic 14</a></li><li><a href=\"#topic-15\">Open Topic 15</a></li><li><a href=\"#topic-16\">Open Topic 16</a></li></ul><h4>Class assignment</h4><p>Project four school bills, map 529 dollars to eligible costs and compare a funding shortfall with borrowing.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-6","title":"Course 1 · Class 6 · Ethics and fiduciary judgment","html":"<h3>Course 1 · Class 6 · Ethics and fiduciary judgment</h3><p><a href=\"#cfp-class-1-5\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-7\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-1\">Open Topic 1</a></li><li><a href=\"#topic-6\">Open Topic 6</a></li></ul><h4>Class assignment</h4><p>Write a recommendation memo comparing a commission-paying product with two alternatives.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-7","title":"Course 1 · Class 7 · Regulation and consumer protection","html":"<h3>Course 1 · Class 7 · Regulation and consumer protection</h3><p><a href=\"#cfp-class-1-6\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-8\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-2\">Open Topic 2</a></li><li><a href=\"#topic-3\">Open Topic 3</a></li><li><a href=\"#topic-4\">Open Topic 4</a></li><li><a href=\"#topic-5\">Open Topic 5</a></li></ul><h4>Class assignment</h4><p>Build a regulator and consumer-protection map for a bank, broker, adviser and insurance producer.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-8","title":"Course 1 · Class 8 · Behavioral bias and client values","html":"<h3>Course 1 · Class 8 · Behavioral bias and client values</h3><p><a href=\"#cfp-class-1-7\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-9\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-65\">Open Topic 65</a></li><li><a href=\"#topic-66\">Open Topic 66</a></li></ul><h4>Class assignment</h4><p>Role-play a client who refuses to sell below their purchase price and identify the decision bias.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-9","title":"Course 1 · Class 9 · Counseling, conflict and crisis","html":"<h3>Course 1 · Class 9 · Counseling, conflict and crisis</h3><p><a href=\"#cfp-class-1-8\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#cfp-class-1-10\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-67\">Open Topic 67</a></li><li><a href=\"#topic-68\">Open Topic 68</a></li><li><a href=\"#topic-69\">Open Topic 69</a></li><li><a href=\"#topic-70\">Open Topic 70</a></li></ul><h4>Class assignment</h4><p>Practice a teach-back after job loss. Document the immediate actions and a decision to defer.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-1-10","title":"Course 1 · Class 10 · Foundations case workshop","html":"<h3>Course 1 · Class 10 · Foundations case workshop</h3><p><a href=\"#cfp-class-1-9\">Previous class</a> · <a href=\"#course-1\">Course syllabus</a> · <a href=\"#course-2\">Open the next course</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-7\">Open Topic 7</a></li><li><a href=\"#topic-8\">Open Topic 8</a></li><li><a href=\"#topic-12\">Open Topic 12</a></li></ul><h4>Class assignment</h4><p>Complete Applied case 1 and revise the plan after a $500 monthly expense increase.</p><p><a href=\"#case-1\">Open the applied case</a></p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.cfp.net/ethics/compliance-resources/2019/09/the-sixth-and-seventh-steps-of-the-financial-planning-process\">CFP Board practice standards</a></p>"},{"id":"cfp-class-2-1","title":"Course 2 · Class 1 · Inventory and prioritize exposures","html":"<h3>Course 2 · Class 1 · Inventory and prioritize exposures</h3><p><a href=\"#course-2\">Course syllabus</a> · <a href=\"#cfp-class-2-2\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the lesson below and the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the example below. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Map insurance exposures to the right contract</h4><p>Start with a loss, the person or entity exposed, the dollars at stake and what losses it can absorb. Decide whether to avoid, reduce, retain or transfer each exposure. Property coverage addresses covered loss to property. Liability coverage addresses specified claims by others. Life insurance provides death benefits. Disability replaces defined earnings and long-term care pays for qualifying care under its terms. Read exclusions, limits and triggers before comparing premiums.</p><h4>Worked example</h4><p>A restaurant fire may damage the oven, interrupt revenue and injure a customer. The damaged oven points to property insurance, interruption to business-income coverage if its terms are met, and the injury to liability. The owner’s illness preventing work raises a separate disability exposure. On the same inventory, compare the household’s health cost-sharing and long-term care funding with its emergency reserves.</p><h4>Practice variation</h4><p>The owner is disabled for 120 days under a policy with a 90-day elimination period. What should you verify before projecting cash receipts?</p><details><summary>Check your work</summary><p>Check disability definition, waiting-period measurement, payment timing, benefit maximum and exclusions. The 90-day waiting period signals a cash gap, but it does not specify when a check will arrive.</p></details><h4>Related topic lessons</h4><ul><li><a href=\"#topic-17\">Open Topic 17</a></li><li><a href=\"#topic-18\">Open Topic 18</a></li></ul><h4>Class assignment</h4><p>Build a severity and funding matrix for household and business losses.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.tdi.texas.gov/consumer/index.html\">Texas Department of Insurance consumer guidance</a></p>"},{"id":"cfp-class-2-2","title":"Course 2 · Class 2 · Health coverage and social insurance","html":"<h3>Course 2 · Class 2 · Health coverage and social insurance</h3><p><a href=\"#cfp-class-2-1\">Previous class</a> · <a href=\"#course-2\">Course syllabus</a> · <a href=\"#cfp-class-2-3\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-19\">Open Topic 19</a></li><li><a href=\"#topic-45\">Open Topic 45</a></li></ul><h4>Class assignment</h4><p>Price an in-network claim under two designs and identify the date to verify public benefits eligibility.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.tdi.texas.gov/consumer/index.html\">Texas Department of Insurance consumer guidance</a></p>"},{"id":"cfp-class-2-3","title":"Course 2 · Class 3 · Disability and workers’ compensation","html":"<h3>Course 2 · Class 3 · Disability and workers’ compensation</h3><p><a href=\"#cfp-class-2-2\">Previous class</a> · <a href=\"#course-2\">Course syllabus</a> · <a href=\"#cfp-class-2-4\">Next class</a></p><h4>Two-hour class</h4><ol><li>10 minutes · Recall what you learned in the previous class or identify what you already know.</li><li>35 minutes · Learn the concepts using the linked topic lessons. Answer each knowledge check before revealing the answer.</li><li>25 minutes · Work through the linked topic questions. Write down the rule, inputs and interpretation.</li><li>10 minutes · Break.</li><li>30 minutes · Complete the class assignment. Explain what changes if an assumption is wrong.</li><li>10 minutes · Explain your conclusion aloud, log anything you missed and mark the class complete.</li></ol><h4>Teaching and worked practice</h4><ul><li><a href=\"#topic-20\">Open Topic 20</a></li></ul><h4>Class assignment</h4><p>Model a waiting-period cash gap. Map occupational and non-occupational events to applicable coverage.</p><p><a target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.tdi.texas.gov/consumer/index.html\">Texas Department of Insurance consumer guidance</a></p>"},{"id":"cfp-class-2-4","title":"Course 2 · Class 4 · Long-term care and caregiving","html":"<h3>Course 2 · Class 4 · Long-term care and caregiving</h3><p><a href=\"#cfp-class-2-3\">Previous class</a> · <